import "array"

// ~96 buckets however far you zoom, floored at the service's 30s stats
// interval, below which there is nothing finer to show; labelled with the
// bucket's start so zooming onto a bar selects what drew it.
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 30000000000 then 30000000000 else spanNs / 96
every = duration(v: everyNs)

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "pcap_dump" and r._field == "written_bytes")
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> map(fn: (r) => ({r with _value: float(v: r._value) / (float(v: everyNs) / 1000000000.0)}))
  |> keep(columns: ["_time", "_value", "_field"])

// ~96 buckets however far you zoom, floored at the service's 30s stats
// interval, below which there is nothing finer to show; labelled with the
// bucket's start so zooming onto a bar selects what drew it.
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 30000000000 then 30000000000 else spanNs / 96
every = duration(v: everyNs)

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "pcap_dump" and r._field == "dropped")
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> map(fn: (r) => ({r with _value: float(v: r._value) / (float(v: everyNs) / 1000000000.0)}))
  |> keep(columns: ["_time", "_value", "_field"])

// ~96 buckets however far you zoom, floored at the service's 30s stats
// interval, below which there is nothing finer to show; labelled with the
// bucket's start so zooming onto a bar selects what drew it.
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 30000000000 then 30000000000 else spanNs / 96
every = duration(v: everyNs)

// The allowance is the budget, or what the files hold plus what the disk can
// still take under pcap_dump.max_disk_percent -- whichever is smaller. When
// it drops below the budget line, something else is filling the disk and the
// capture is giving way to it.
from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "pcap_dump")
  |> filter(fn: (r) => r._field == "bytes" or r._field == "allowance_bytes" or r._field == "budget_bytes")
  |> aggregateWindow(every: every, fn: last, timeSrc: "_start", createEmpty: false)
  |> keep(columns: ["_time", "_value", "_field"])

// `detail` carries the scope (and a note, if the call was made by hand with
// &note=...); the action is a tag, so no pivot is needed.
from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "pcap_dump_control" and r._field == "detail")
  |> keep(columns: ["_time", "action", "_value"])
  |> group()
  |> sort(columns: ["_time"], desc: true)
  |> limit(n: 200)
